# ============================================================================
# 190x4 - STEAM CLASS MAP probe (steam-theming-utils extractor via our CDP harness)
# Runs ricewind012's class_modules extractor (webpack enum + maintained db/client
# + class_modules) over CDP against the SharedJSContext target. Avoids the broken
# find-process dep in the npm tool; needs only Steam running with CEF debugging
# (Millennium provides it) on :8080. Output: client.json on the Desktop -> send it.
# Run: powershell -ExecutionPolicy Bypass -File C:\Users\Administrator\Desktop\class-map.ps1
# ============================================================================
$ErrorActionPreference = 'Stop'
$log = Join-Path ([Environment]::GetFolderPath('Desktop')) 'class-map-log.txt'
try { Start-Transcript -Path $log -Force | Out-Null } catch {}

# extractor JS (base64 of the combined CDP scripts) -> decode to expression
$b64 = ''
$expr = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))

function Probe-Target($wsUrl, $expression) {
  $ws = [System.Net.WebSockets.ClientWebSocket]::new()
  $cts = New-Object Threading.CancellationTokenSource 60000
  $ct = $cts.Token
  $ws.ConnectAsync([Uri]$wsUrl, $ct).Wait()
  $payload = @{ id = 1; method = 'Runtime.evaluate'; params = @{ expression = $expression; awaitPromise = $true; returnByValue = $true } } | ConvertTo-Json -Depth 8 -Compress
  $buf = [Text.Encoding]::UTF8.GetBytes($payload)
  $ws.SendAsync([ArraySegment[byte]]::new($buf), 'Text', $true, $ct).Wait()
  $recv = New-Object byte[] 1048576
  $val = $null
  for ($i = 0; $i -lt 120 -and -not $val; $i++) {
    $sb = New-Object Text.StringBuilder
    do {
      $seg = [ArraySegment[byte]]::new($recv)
      $r = $ws.ReceiveAsync($seg, $ct); $r.Wait()
      [void]$sb.Append([Text.Encoding]::UTF8.GetString($recv, 0, $r.Result.Count))
    } while (-not $r.Result.EndOfMessage)
    $o = $sb.ToString() | ConvertFrom-Json
    if ($o.id -eq 1) {
      if ($o.error) { throw $o.error.message }
      if ($o.result.result.exceptionDetails) { throw ($o.result.result.exceptionDetails | ConvertTo-Json -Depth 6) }
      $val = $o.result.result.value
    }
  }
  $ws.Dispose()
  return $val
}

try {
  $targets = Invoke-RestMethod 'http://localhost:8080/json'
  $t = $targets | Where-Object { $_.title -eq 'SharedJSContext' -and $_.webSocketDebuggerUrl } | Select-Object -First 1
  if (-not $t) { throw "SharedJSContext target not found. Is Steam (Millennium) running on :8080?" }
  Write-Host ("probing [{0}] {1}" -f $t.title, $t.webSocketDebuggerUrl)
  $raw = Probe-Target $t.webSocketDebuggerUrl $expr
  if (-not $raw) { throw "No result returned (timeout?)." }
  $res = $raw | ConvertFrom-Json
  if (-not $res.ok) { throw ("extractor error: " + $res.err) }
  $out = Join-Path ([Environment]::GetFolderPath('Desktop')) 'client.json'
  # $res.data is already a JSON string (kept as string to avoid PowerShell's
  # case-insensitive key collision on e.g. active/Active) -> write verbatim.
  [IO.File]::WriteAllText($out, $res.data, [Text.Encoding]::UTF8)
  Write-Host ""
  Write-Host ("Modules captured: {0}" -f $res.n)
  Write-Host ("Saved: {0}" -f $out)
  Write-Host ">>> Send client.json back."
}
catch {
  Write-Host ""
  Write-Host ("ERROR: {0}" -f $_.Exception.Message) -ForegroundColor Red
}
finally {
  try { Stop-Transcript | Out-Null } catch {}
  Read-Host "Press Enter to close"
}
